            aOrbiterC = ((aWandererF + RotL64(aScatter, 27U)) + 0x5EBDD35DA4EFAE36ULL) + aOASaltB[(((511U - aIndex) + 429U)) & S_SALT1];
            aOrbiterB = (((aWandererI + RotL64(aIngress, 11U)) + RotL64(aCarry, 57U)) + 0x567C4B7219A6AB81ULL) + aOASaltD[((aIndex + 221U)) & S_SALT1];
