            aOrbiterB = (((aWandererF + RotL64(aPrevious, 11U)) + RotL64(aCarry, 21U)) + 0xE91EB1B46EDD7010ULL) + aOASaltC[(((511U - aIndex) + 500U)) & S_SALT1];
            aOrbiterE = ((aWandererC + RotL64(aScatter, 19U)) + 0xCA1484339DEABF63ULL) + aOASaltA[((aIndex + 19U)) & S_SALT1];
