            aOrbiterA = ((aWandererF + RotL64(aScatter, 27U)) + RotL64(aCarry, 41U)) + 0x2D4DECEDA3998CB3ULL;
            aOrbiterH = ((aWandererK + RotL64(aIngress, 3U)) + 0x42E0FAC456A5E608ULL) + aOASaltH[(((511U - aIndex) + 319U)) & S_SALT1];
