            aOrbiterA = ((aWandererI + RotL64(aIngress, 50U)) + 0xA7B4269027E4B8BAULL) + aOASaltD[(((511U - aIndex) + 395U)) & S_SALT1];
            aOrbiterJ = (aWandererB + RotL64(aScatter, 3U)) + 0x6E121B6554A2A192ULL;
            aOrbiterE = (aWandererD + RotL64(aIngress, 39U)) + 0x353C12E42D615DE2ULL;
            aOrbiterD = (aWandererC + RotL64(aPrevious, 47U)) + 0x374DA572F9446DF0ULL;
            //
            aOrbiterH = ((aOrbiterH + aOrbiterI) + 0x7C4639346A1991B7ULL) + aOUSaltG[(((511U - aIndex) + 288U)) & S_SALT1];
